def load_config(path):
    f = None
    try:
        f = open(path)
        config = f.read()
    except FileNotFoundError:
        print("Config not found, using defaults")
        config = "default"
    else:
        print("Config loaded")
    finally:
        if f:
            f.close()
    return config
